import { z } from "zod"

import {
  decimalText,
  toDecimal,
  toNumberText,
} from "@/components/openlmis/number-text"
import type { NamedOption } from "@/components/blocks/openlmis/product-program-link-dialog/program-link-form"

/** How much stock facilities of one type keep, in periods of use. */
export type ApprovalStock = {
  maxPeriodsOfStock: number
  emergencyOrderPoint: number | null
  minPeriodsOfStock: number | null
}

/** One facility type approved to stock the product in one program. */
export type Approval = ApprovalStock & {
  id: string
  facilityType: NamedOption
  program: NamedOption
}

/** What Add and Save hand back: the pair is only set when adding, since an edit keeps it. */
export type ApprovalValues = ApprovalStock & {
  facilityTypeId: string
  programId: string
}

const periods = (optional: boolean) =>
  decimalText(
    {
      required: "Enter the most periods of stock.",
      invalid: "Enter a number of 0 or more, such as 3 or 1.5.",
      tooLarge: "Enter a smaller number.",
    },
    { optional }
  )

/** Refuses a facility type and program pair already approved, other than the one being edited. */
export function approvalFormSchema(
  approved: readonly Approval[],
  editingId?: string
) {
  return z
    .object({
      facilityTypeId: z
        .string()
        .nullable()
        .refine(Boolean, "Choose a facility type."),
      programId: z.string().nullable().refine(Boolean, "Choose a program."),
      maxPeriodsOfStock: periods(false),
      emergencyOrderPoint: periods(true),
      minPeriodsOfStock: periods(true),
    })
    .superRefine((values, context) => {
      const taken = approved.some(
        (approval) =>
          approval.id !== editingId &&
          approval.facilityType.id === values.facilityTypeId &&
          approval.program.id === values.programId
      )
      if (taken) {
        context.addIssue({
          code: "custom",
          path: ["programId"],
          message:
            "This facility type already stocks the product in this program.",
        })
      }
    })
}

export type ApprovalFormValues = z.input<ReturnType<typeof approvalFormSchema>>

export const EMPTY_APPROVAL_FORM: ApprovalFormValues = {
  facilityTypeId: null,
  programId: null,
  maxPeriodsOfStock: "",
  emergencyOrderPoint: "",
  minPeriodsOfStock: "",
}

export function toApprovalFormValues(approval: Approval): ApprovalFormValues {
  return {
    facilityTypeId: approval.facilityType.id,
    programId: approval.program.id,
    maxPeriodsOfStock: toNumberText(approval.maxPeriodsOfStock),
    emergencyOrderPoint: toNumberText(approval.emergencyOrderPoint),
    minPeriodsOfStock: toNumberText(approval.minPeriodsOfStock),
  }
}

export function toApprovalValues(values: ApprovalFormValues): ApprovalValues {
  return {
    facilityTypeId: values.facilityTypeId ?? "",
    programId: values.programId ?? "",
    maxPeriodsOfStock: toDecimal(values.maxPeriodsOfStock) ?? 0,
    emergencyOrderPoint: toDecimal(values.emergencyOrderPoint),
    minPeriodsOfStock: toDecimal(values.minPeriodsOfStock),
  }
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useMemo } from "react"

import { FieldGroup } from "@/components/ui/field"
import type { NamedOption } from "@/components/blocks/openlmis/product-program-link-dialog/program-link-form"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  type Approval,
  approvalFormSchema,
  type ApprovalValues,
  EMPTY_APPROVAL_FORM,
  toApprovalFormValues,
  toApprovalValues,
} from "@/components/blocks/openlmis/product-approval-dialog/approval-form"

/** `"new"` adds a facility type; an approval id edits, or views, that approval. */
export type ApprovalDialogTarget = "new" | (string & {})

type ProductApprovalDialogProps = {
  /** Opens the dialog while set. */
  target: ApprovalDialogTarget | undefined
  productName: string
  /** The product's approvals; the form shows a skeleton until they are set. */
  approvals: readonly Approval[] | undefined
  /** Every facility type; the form shows a skeleton until they are set. */
  facilityTypes: readonly NamedOption[] | undefined
  /** The programs the product is in, the only ones it can be approved for. */
  programs: readonly NamedOption[] | undefined
  /** Shows the approval without letting it change. */
  readOnly?: boolean
  /** Called with the values to save; save them, then clear `target`. */
  onSubmit: (values: ApprovalValues, existing?: Approval) => void
  /** Keeps the dialog open and spins the submit while the save runs. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed; what was typed stays. */
  error?: ReactNode
  onClose: () => void
}

/** Let a type of facility stock the product in a program, or change how much it keeps. */
export function ProductApprovalDialog({
  target,
  pending = false,
  onClose,
  ...props
}: ProductApprovalDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown !== undefined && (
        <ApprovalContent
          key={shown}
          pending={pending}
          target={shown}
          {...props}
        />
      )}
    </FormDialog>
  )
}

type ContentProps = Omit<ProductApprovalDialogProps, "target" | "onClose"> & {
  target: ApprovalDialogTarget
  pending: boolean
}

function ApprovalContent({
  target,
  approvals,
  facilityTypes,
  programs,
  readOnly = false,
  ...props
}: ContentProps) {
  const adding = target === "new"
  const title = adding ? "Add Facility Type" : "Facility Type"

  if (!approvals || !facilityTypes || !programs) {
    return (
      <ApprovalSkeleton adding={adding} readOnly={readOnly} title={title} />
    )
  }
  const approval = approvals.find((item) => item.id === target)
  if (!adding && !approval) {
    return (
      <>
        <FormDialogHeader>
          <FormDialogTitle>{title}</FormDialogTitle>
          <FormDialogDescription>
            This facility type no longer stocks the product.
          </FormDialogDescription>
        </FormDialogHeader>
        <FormDialogFooter>
          <FormDialogCancel>Close</FormDialogCancel>
        </FormDialogFooter>
      </>
    )
  }
  return (
    <ApprovalForm
      approval={approval}
      approvals={approvals}
      facilityTypes={facilityTypes}
      programs={programs}
      readOnly={readOnly}
      {...props}
    />
  )
}

type ApprovalFormProps = Omit<
  ContentProps,
  "target" | "approvals" | "facilityTypes" | "programs"
> & {
  approval: Approval | undefined
  approvals: readonly Approval[]
  facilityTypes: readonly NamedOption[]
  programs: readonly NamedOption[]
  readOnly: boolean
}

const byLabel = (a: { label: string }, b: { label: string }) =>
  a.label.localeCompare(b.label)

function ApprovalForm({
  approval,
  approvals,
  facilityTypes,
  programs,
  productName,
  readOnly,
  onSubmit,
  pending,
  error,
}: ApprovalFormProps) {
  const schema = useMemo(
    () => approvalFormSchema(approvals, approval?.id),
    [approvals, approval]
  )
  const facilityTypeItems = useMemo(
    () =>
      facilityTypes
        .map((type) => ({ value: type.id, label: type.name }))
        // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
        .sort(byLabel),
    [facilityTypes]
  )
  const programItems = useMemo(() => {
    const items = programs.map((program) => ({
      value: program.id,
      label: program.name,
    }))
    // An approval for a program the product has since left still shows its program.
    if (approval && !items.some((item) => item.value === approval.program.id)) {
      items.push({ value: approval.program.id, label: approval.program.name })
    }
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh array; toSorted needs the ES2023 lib
    return items.sort(byLabel)
  }, [programs, approval])

  const form = useAppForm({
    defaultValues: approval
      ? toApprovalFormValues(approval)
      : EMPTY_APPROVAL_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(toApprovalValues(value), approval),
  })

  const facilityType = approval?.facilityType.name
  const title = !approval
    ? "Add Facility Type"
    : readOnly
      ? (facilityType ?? "")
      : `Edit ${facilityType}`

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <FormDialogDescription>
          {approval
            ? `How much ${productName} facilities of type ${facilityType} keep for ${approval.program.name}.`
            : `Let a type of facility stock ${productName} in one of its programs.`}
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Facility Type"
            />
          )}
          <form.AppField name="facilityTypeId">
            {(field) => (
              <field.ComboboxField
                clearLabel="Clear Facility Type"
                description={
                  approval && !readOnly
                    ? "The facility type and program stay as they are; remove this one and add another to change them."
                    : undefined
                }
                disabled={Boolean(approval)}
                emptyMessage="No facility types match."
                items={facilityTypeItems}
                label="Facility Type"
                placeholder="Choose A Facility Type"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="programId">
            {(field) => (
              <field.ComboboxField
                clearLabel="Clear Program"
                description={
                  approval ? undefined : "Only the programs the product is in."
                }
                disabled={Boolean(approval)}
                emptyMessage="Add the product to a program first."
                items={programItems}
                label="Program"
                placeholder="Choose A Program"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="maxPeriodsOfStock">
            {(field) => (
              <field.DecimalField
                description="The most stock a facility keeps, in periods of use."
                disabled={readOnly}
                label="Max Periods Of Stock"
                required
              />
            )}
          </form.AppField>
          <div className="grid gap-5 @md/field-group:grid-cols-2">
            <form.AppField name="emergencyOrderPoint">
              {(field) => (
                <field.DecimalField
                  description="Stock, in periods, below which a facility orders at once."
                  disabled={readOnly}
                  label="Emergency Order Point"
                />
              )}
            </form.AppField>
            <form.AppField name="minPeriodsOfStock">
              {(field) => (
                <field.DecimalField
                  description="The least stock a facility keeps, in periods of use."
                  disabled={readOnly}
                  label="Min Periods Of Stock"
                />
              )}
            </form.AppField>
          </div>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending}>
          {readOnly ? "Close" : "Cancel"}
        </FormDialogCancel>
        {!readOnly && (
          <FormDialogSubmit pending={pending}>
            {approval ? "Save" : "Add Facility Type"}
          </FormDialogSubmit>
        )}
      </FormDialogFooter>
    </FormDialogForm>
  )
}

type ApprovalSkeletonProps = {
  title: string
  adding: boolean
  readOnly: boolean
}

/** The form as it will look, so nothing moves when its choices arrive. */
function ApprovalSkeleton({ title, adding, readOnly }: ApprovalSkeletonProps) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Facility Type" required />
            <FieldSkeleton label="Program" required />
            <FieldSkeleton label="Max Periods Of Stock" required />
            <div className="grid gap-5 @md/field-group:grid-cols-2">
              <FieldSkeleton label="Emergency Order Point" />
              <FieldSkeleton label="Min Periods Of Stock" />
            </div>
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel>{readOnly ? "Close" : "Cancel"}</FormDialogCancel>
        {!readOnly && (
          <FormDialogSubmit disabled>
            {adding ? "Add Facility Type" : "Save"}
          </FormDialogSubmit>
        )}
      </FormDialogFooter>
    </>
  )
}
